void test_is_not_equal(my_decimal decimal1, my_decimal decimal2, int check) {
  int code = my_is_not_equal(decimal1, decimal2);

#if defined(__DEBUG)
  printf("---------------------------------\n");
  printf("Tests:\n");
  my_print_decimal_bits(decimal1);
  my_print_decimal_string(decimal1);
  my_print_decimal_bits(decimal2);
  my_print_decimal_string(decimal2);
  printf("Check: %d\n", check);
  printf("Result: %d\n", code);
  printf("---------------------------------\n");
#endif

  ck_assert_int_eq(code, check);
}
